const cookie = $input.first().json.cookie;
const cursos = [
  { cursoId: 11, nombreCurso: 'P01 - Base de Datos, Data Warehouse y Data Lake I' },
  { cursoId: 5, nombreCurso: 'P02 - Privacidad al Usar Herramientas de IA' },
  { cursoId: 6, nombreCurso: 'P03 - ETL y ELT para Procesos de Datos' },
  { cursoId: 7, nombreCurso: 'P04 - Backend: Fundamentos para Aplicaciones Web' },
  { cursoId: 8, nombreCurso: 'P05 - Agentes de IA: Conceptos y Aplicaciones' },
  { cursoId: 9, nombreCurso: 'P06 - Pricing: Estrategias para Definir Precios' }
];
return cursos.map(c => ({ json: { ...c, cookie } }));

const items = $input.all();
const cursosItems = $('Generar lista de cursos').all();
const results = [];
items.forEach((item, idx) => {
  const html = item.json.data || '';
  const cursoId = cursosItems[idx].json.cursoId;
  const nombreCurso = cursosItems[idx].json.nombreCurso;
  const cookie = cursosItems[idx].json.cookie;
  const itemRegex = /<div class="list-title">([^<]+)<\/div>[\s\S]*?<span class="chip chip-ok">Publicada<\/span>[\s\S]*?\/docente\/clases\/(\d+)">Abrir<\/a>/g;
  let m;
  while ((m = itemRegex.exec(html)) !== null) {
    results.push({ json: { cursoId, nombreCurso, claseTitulo: m[1].trim(), claseId: parseInt(m[2], 10), cookie }, pairedItem: idx });
  }
});
return results;

const html = $json.data || '';
const cursoId = $('Extraer clases publicadas').item.json.cursoId;
const nombreCurso = $('Extraer clases publicadas').item.json.nombreCurso;
const claseId = $('Extraer clases publicadas').item.json.claseId;
const claseTitulo = $('Extraer clases publicadas').item.json.claseTitulo;

function clean(s) {
  return String(s)
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&eacute;/g, 'é').replace(/&aacute;/g, 'á').replace(/&iacute;/g, 'í').replace(/&oacute;/g, 'ó').replace(/&uacute;/g, 'ú').replace(/&ntilde;/g, 'ñ')
    .replace(/\s+/g, ' ')
    .trim();
}

let transcripcion = '';
const tm = html.match(/<p class="small prewrap" style="max-height:420px;overflow:auto">([\s\S]*?)<\/p><\/details>/);
if (tm) transcripcion = clean(tm[1]);

const temas = [];
const temaBlockMatch = html.match(/<section class="card" id="temas"[\s\S]*?<ul class="list small">([\s\S]*?)<\/ul>/);
if (temaBlockMatch) {
  const temaRegex = /<strong>([^<]+)<\/strong>/g;
  let tmo;
  while ((tmo = temaRegex.exec(temaBlockMatch[1])) !== null) temas.push(clean(tmo[1]));
}
const resumen = temas.length ? ('Temas cubiertos en esta clase:\n- ' + temas.join('\n- ')) : '';

const retoRegex = /<article class="reto-card" id="reto-(\d+)">([\s\S]*?)<\/article>/g;
const retos = [];
let rm;
while ((rm = retoRegex.exec(html)) !== null) {
  const block = rm[2];
  const temaM = block.match(/<dt>Tema<\/dt><dd>([\s\S]*?)<\/dd>/);
  const detM = block.match(/<details[^>]*>([\s\S]*?)<\/details>/);
  let pregunta = '', explicacion = '', pista1 = '', respuesta = '';
  if (detM) {
    const d = detM[1];
    const pM = d.match(/<p class="prewrap"><strong>([\s\S]*?)<\/strong><\/p>/);
    if (pM) pregunta = clean(pM[1]);
    const expM = d.match(/<dt>Explicaci[oó]n<\/dt><dd class="prewrap">([\s\S]*?)<\/dd>/);
    if (expM) explicacion = clean(expM[1]);
    const p1 = d.match(/<dt>Pista 1<\/dt><dd>([\s\S]*?)<\/dd>/);
    if (p1) pista1 = clean(p1[1]);
    const rmo = d.match(/<dt>Respuesta modelo<\/dt><dd class="prewrap">([\s\S]*?)<\/dd>/);
    if (rmo) respuesta = clean(rmo[1]);
    const altM = d.match(/<div class="opt-ok">✓ ([\s\S]*?)<\/div>/);
    if (!respuesta && altM) respuesta = clean(altM[1]);
    const compM = d.match(/<dt>Respuestas aceptadas<\/dt><dd>([\s\S]*?)<\/dd>/);
    if (!respuesta && compM) respuesta = clean(compM[1]);
  }
  retos.push({ tema: temaM ? clean(temaM[1]) : '', pregunta, pista1, explicacion, respuesta });
}

const tareaEnunciado = retos.map((r, i) => `Reto ${i + 1} (${r.tema}): ${r.pregunta}\nPista: ${r.pista1}`).join('\n\n');
const solucionReferencia = retos.map((r, i) => `Reto ${i + 1} (${r.tema}): ${r.pregunta}\nRespuesta/clave: ${r.respuesta}\nExplicación: ${r.explicacion}`).join('\n\n');

return { json: {
  id: `web-curso${cursoId}-clase${claseId}`,
  titulo: `${nombreCurso} · ${claseTitulo}`,
  resumen,
  transcripcion,
  tareaNombre: `Retos de ${claseTitulo}`,
  tareaEnunciado,
  tareaFechaEntrega: '',
  proximaClase: '',
  solucionReferencia,
  cursoId,
  claseId
} };
